// Previous D GPU LDR compositor, for differential tests only.
/** Experimental D light/warp field over the live terrain. LDR only, no HDR,
 * bloom pyramid, viewport post or actor depth; not P0 parity. */
import type {BTransform} from '../../src/arcana_b/anchors';import type {DWarp} from '../../src/arcana_d/warp';import type {DCommand} from '../../src/arcana_d/commands';import {dInfluence} from '../../src/arcana_d/influence';
const VS=`#version 300 es
in vec2 pos;void main(){gl_Position=vec4(pos,0.,1.);}`;
const FS=`#version 300 es
precision highp float;precision highp int;uniform sampler2D scene;uniform sampler2D light;uniform sampler2D warp;uniform sampler2D influence;uniform vec2 size;uniform vec2 camera;uniform vec4 basis;uniform vec2 origin;uniform float time;uniform float fade;out vec4 color;
float bayer(ivec2 p){int a[16]=int[16](0,8,2,10,12,4,14,6,3,11,1,9,15,7,13,5);return(float(a[(p.y&3)*4+(p.x&3)])+.5)/16.;}
vec3 tone(vec3 c,ivec2 p){c=clamp((c*(2.51*c+.03))/(c*(2.43*c+.59)+.14),0.,1.);float l=dot(c,vec3(.2126,.7152,.0722));c=clamp(mix(vec3(l),c,1.1),0.,1.);return floor(c*26.+vec3(bayer(p)))/26.;}
vec3 sceneAt(vec2 xy){return texture(scene,vec2(clamp(xy.x/size.x,0.,1.),clamp(1.-xy.y/size.y,0.,1.))).rgb;}
vec3 sampleWorld(vec2 pixel,vec2 d){return sceneAt(pixel+vec2(basis.x*d.x+basis.z*d.y,basis.y*d.x+basis.w*d.y));}
void main(){vec2 pixel=vec2(gl_FragCoord.x,size.y-gl_FragCoord.y),w=pixel+camera-origin;vec3 original=sceneAt(pixel);float det=basis.x*basis.w-basis.y*basis.z;ivec2 p=ivec2(floor(vec2(basis.w*w.x-basis.z*w.y,-basis.y*w.x+basis.x*w.y)/det));if(p.x<0||p.y<0||p.x>=480||p.y>=270||texelFetch(influence,p,0).r<.5){color=vec4(original,1.);return;}
 vec4 v=texelFetch(warp,p,0)*clamp(fade,0.,1.);vec2 off=-v.xy;vec3 warped=vec3(sampleWorld(pixel,off*1.35).r,sampleWorld(pixel,off).g,sampleWorld(pixel,off*.65).b);warped*=1.-clamp(v.z,0.,.985);float uy=1.-(float(p.y)+.5)/270.;warped*=1.+v.w*.10*sin(uy*180.+time*8.);vec3 l=texelFetch(light,p,0).rgb;vec3 delta=tone(warped+l,p)-tone(original,p);color=vec4(clamp(original+delta*clamp(fade,0.,1.),0.,1.),1.);}`;
export class DWorldGpu{
 readonly canvas:HTMLCanvasElement;private gl:WebGL2RenderingContext;private p:WebGLProgram;private textures:WebGLTexture[]=[];private inf=new Float32Array(480*270*4);
 constructor(w:number,h:number){this.canvas=document.createElement('canvas');this.canvas.width=w;this.canvas.height=h;const gl=this.canvas.getContext('webgl2',{alpha:false,antialias:false,premultipliedAlpha:false,preserveDrawingBuffer:true});if(!gl)throw new Error('WebGL2 unavailable');this.gl=gl;const compile=(kind:number,src:string)=>{const sh=gl.createShader(kind)!;gl.shaderSource(sh,src);gl.compileShader(sh);if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS))throw new Error(gl.getShaderInfoLog(sh)||'shader');return sh;};const p=gl.createProgram()!;gl.attachShader(p,compile(gl.VERTEX_SHADER,VS));gl.attachShader(p,compile(gl.FRAGMENT_SHADER,FS));gl.linkProgram(p);if(!gl.getProgramParameter(p,gl.LINK_STATUS))throw new Error(gl.getProgramInfoLog(p)||'link');this.p=p;gl.useProgram(p);const b=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,b);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);const pos=gl.getAttribLocation(p,'pos');gl.enableVertexAttribArray(pos);gl.vertexAttribPointer(pos,2,gl.FLOAT,false,0,0);for(let i=0;i<4;i++){const tex=gl.createTexture()!;this.textures.push(tex);gl.activeTexture(gl.TEXTURE0+i);gl.bindTexture(gl.TEXTURE_2D,tex);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.NEAREST);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.NEAREST);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);gl.uniform1i(gl.getUniformLocation(p,['scene','light','warp','influence'][i]),i);}gl.disable(gl.BLEND);gl.disable(gl.DITHER);gl.viewport(0,0,w,h);}
 render(scene:HTMLCanvasElement,light:HTMLCanvasElement,commands:DCommand[],warp:DWarp,m:BTransform,cx:number,cy:number,time:number,fade:number){const gl=this.gl,p=this.p;gl.useProgram(p);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,1);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,this.textures[0]);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,scene);gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL,0);gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,this.textures[1]);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,light);gl.activeTexture(gl.TEXTURE2);gl.bindTexture(gl.TEXTURE_2D,this.textures[2]);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA32F,480,270,0,gl.RGBA,gl.FLOAT,warp.data);const influence=dInfluence(commands,warp);for(let i=0;i<influence.length;i++)this.inf[i*4]=influence[i];gl.activeTexture(gl.TEXTURE3);gl.bindTexture(gl.TEXTURE_2D,this.textures[3]);gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA32F,480,270,0,gl.RGBA,gl.FLOAT,this.inf);gl.uniform2f(gl.getUniformLocation(p,'size'),this.canvas.width,this.canvas.height);gl.uniform2f(gl.getUniformLocation(p,'camera'),cx,cy);gl.uniform4f(gl.getUniformLocation(p,'basis'),m.a,m.b,m.c,m.d);gl.uniform2f(gl.getUniformLocation(p,'origin'),m.x,m.y);gl.uniform1f(gl.getUniformLocation(p,'time'),time);gl.uniform1f(gl.getUniformLocation(p,'fade'),fade);gl.drawArrays(gl.TRIANGLE_STRIP,0,4);}
}
